public class CommandLineSplitterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static final String[] ARGS = {"build", "--verbose", "--out=dist", "main.java", "--",
            "--not-an-option", "-v"};

    public static void main(String[] args) {
        try {
            java.util.Map<String, String> options = CommandLineSplitter.options(ARGS);
            check("options size", 2, options == null ? -1 : options.size());
            check("options flag becomes true", "true", options == null ? null : options.get("verbose"));
            check("options key=value", "dist", options == null ? null : options.get("out"));
            check("option after the separator is ignored", null,
                    options == null ? "missing map" : options.get("not-an-option"));

            java.util.List<String> rest = CommandLineSplitter.positionals(ARGS);
            check("positionals", "[build, main.java, --not-an-option, -v]",
                    rest == null ? "null" : rest.toString());

            java.util.Map<String, String> last = CommandLineSplitter.options(
                    new String[] {"--mode=fast", "--mode=slow"});
            check("duplicate option -- last wins", "slow", last == null ? null : last.get("mode"));

            java.util.Map<String, String> emptyValue = CommandLineSplitter.options(
                    new String[] {"--tag="});
            check("empty value after the equals sign", "", emptyValue == null ? null : emptyValue.get("tag"));

            java.util.Map<String, String> noOptions = CommandLineSplitter.options(new String[] {"a", "b"});
            check("no options at all", 0, noOptions == null ? -1 : noOptions.size());

            check("separator itself is never positional", "[a]",
                    CommandLineSplitter.positionals(new String[] {"a", "--"}).toString());
            check("empty args give an empty list", "[]",
                    CommandLineSplitter.positionals(new String[] {}).toString());
        } catch (RuntimeException ex) {
            System.out.println("FAIL  a method threw " + ex);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

