public class CommandLineSplitter {

    public static java.util.Map<String, String> options(String[] args) {
        java.util.Map<String, String> found = new java.util.LinkedHashMap<>();
        boolean afterSeparator = false;
        for (String arg : args) {
            if (afterSeparator) {
                continue;
            }
            if (arg.equals("--")) {
                afterSeparator = true;
            } else if (arg.startsWith("--")) {
                String body = arg.substring(2);
                int equals = body.indexOf('=');
                if (equals >= 0) {
                    found.put(body.substring(0, equals), body.substring(equals + 1));
                } else {
                    found.put(body, "true");
                }
            }
        }
        return found;
    }

    public static java.util.List<String> positionals(String[] args) {
        java.util.List<String> found = new java.util.ArrayList<>();
        boolean afterSeparator = false;
        for (String arg : args) {
            if (afterSeparator) {
                found.add(arg);
            } else if (arg.equals("--")) {
                afterSeparator = true;
            } else if (!arg.startsWith("--")) {
                found.add(arg);
            }
        }
        return found;
    }
}
